    刷新或迁移源 MAC。累计等于上限合法，首次超过即抛 ForwardWorkLimit。
    """
    by_name = {port["name"]: port for port in ports}
    width = len(ports) + 1
    fdb = {}  # (vlan, mac) -> [port, seen]
    work = 0
    for t, port_name, src, dst, tag in frames:
